1	package main
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	
9		"github.com/asdhoaiqqq/chainledger-governance/chainledger"
10	)
11	
12	// writeFile creates a file in the test's temp directory with the given content.
13	func writeFile(t *testing.T, name, content string) string {
14		t.Helper()
15		path := filepath.Join(t.TempDir(), name)
16		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
17			t.Fatalf("WriteFile %q: %v", name, err)
18		}
19		return path
20	}
21	
22	// readFile returns the file content.
23	func readFile(t *testing.T, path string) string {
24		t.Helper()
25		data, err := os.ReadFile(path)
26		if err != nil {
27			t.Fatalf("ReadFile %q: %v", path, err)
28		}
29		return string(data)
30	}
31	
32	// captureStdout runs fn with os.Stdout and os.Stderr redirected to pipes,
33	// returning what was written to each.
34	func captureStdout(t *testing.T, fn func() int) (stdout, stderr string, exit int) {
35		t.Helper()
36		oldStdout := os.Stdout
37		oldStderr := os.Stderr
38		rOut, wOut, err := os.Pipe()
39		if err != nil {
40			t.Fatalf("pipe: %v", err)
41		}
42		rErr, wErr, err := os.Pipe()
43		if err != nil {
44			t.Fatalf("pipe: %v", err)
45		}
46		os.Stdout = wOut
47		os.Stderr = wErr
48	
49		exit = fn()
50	
51		wOut.Close()
52		wErr.Close()
53		outBytes, _ := readAll(rOut)
54		errBytes, _ := readAll(rErr)
55		os.Stdout = oldStdout
56		os.Stderr = oldStderr
57		return string(outBytes), string(errBytes), exit
58	}
59	
60	func readAll(f *os.File) ([]byte, error) {
61		var out []byte
62		buf := make([]byte, 4096)
63		for {
64			n, err := f.Read(buf)
65			out = append(out, buf[:n]...)
66			if err != nil {
67				break
68			}
69		}
70		return out, nil
71	}
72	
73	func TestCLIPreviewKeepsGraphFile(t *testing.T) {
74		graphPath := writeFile(t, "graph.json", `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`)
75		planPath := writeFile(t, "plan.json", `{"changes":[{"name":"A","upstreams":["B"]},{"name":"B","upstreams":[]}]}`)
76	
77		original := readFile(t, graphPath)
78		stdout, stderr, exit := captureStdout(t, func() int {
79			return run([]string{"preview", graphPath, planPath})
80		})
81		if exit != 0 {
82			t.Fatalf("preview exit = %d, stderr = %s", exit, stderr)
83		}
84		if !strings.Contains(stdout, `"changedDatasets"`) {
85			t.Errorf("preview stdout missing report: %s", stdout)
86		}
87		// The graph file must be byte-for-byte unchanged after preview.
88		got := readFile(t, graphPath)
89		if got != original {
90			t.Errorf("graph file changed after preview:\n got %s\nwant %s", got, original)
91		}
92	}
93	
94	func TestCLIApplyWritesGraphBack(t *testing.T) {
95		graphPath := writeFile(t, "graph.json", `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`)
96		planPath := writeFile(t, "plan.json", `{"changes":[{"name":"A","upstreams":["B"]},{"name":"B","upstreams":[]}]}`)
97	
98		stdout, stderr, exit := captureStdout(t, func() int {
99			return run([]string{"apply", graphPath, planPath})
100		})
101		if exit != 0 {
102			t.Fatalf("apply exit = %d, stderr = %s", exit, stderr)
103		}
104		if !strings.Contains(stdout, `"finalGraph"`) {
105			t.Errorf("apply stdout missing report: %s", stdout)
106		}
107		// The graph file must now reflect the final graph: A depends on B, B root.
108		got := readFile(t, graphPath)
109		if !strings.Contains(got, `"B"`) {
110			t.Errorf("graph file not updated after apply: %s", got)
111		}
112		// Re-read and unmarshal to verify the structure is correct.
113		graph, err := chainledger.UnmarshalGraphFile([]byte(got))
114		if err != nil {
115			t.Fatalf("written graph file is invalid: %v", err)
116		}
117		if got := graph["A"].Parents; len(got) != 1 || got[0] != "B" {
118			t.Errorf("A.Parents = %v, want [B]", got)
119		}
120		if got := graph["B"].Parents; len(got) != 0 {
121			t.Errorf("B.Parents = %v, want empty (root)", got)
122		}
123	}
124	
125	func TestCLIApplyRejectionPreservesGraphFile(t *testing.T) {
126		graphPath := writeFile(t, "graph.json", `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`)
127		// Plan that creates a cycle: A depends on B, B depends on A.
128		planPath := writeFile(t, "plan.json", `{"changes":[{"name":"A","upstreams":["B"]},{"name":"B","upstreams":["A"]}]}`)
129	
130		original := readFile(t, graphPath)
131		stdout, stderr, exit := captureStdout(t, func() int {
132			return run([]string{"apply", graphPath, planPath})
133		})
134		if exit == 0 {
135			t.Fatalf("apply expected non-zero exit on cycle, got 0")
136		}
137		if !strings.Contains(stderr, "cycle") {
138			t.Errorf("stderr = %q, want cycle error", stderr)
139		}
140		if stdout != "" {
141			t.Errorf("stdout = %q, want empty on rejection", stdout)
142		}
143		// The graph file must be completely preserved.
144		got := readFile(t, graphPath)
145		if got != original {
146			t.Errorf("graph file changed after rejected apply:\n got %s\nwant %s", got, original)
147		}
148	}
149	
150	func TestCLIMissingFileReturnsError(t *testing.T) {
151		planPath := writeFile(t, "plan.json", `{"changes":[]}`)
152		_, stderr, exit := captureStdout(t, func() int {
153			return run([]string{"preview", "/nonexistent/graph.json", planPath})
154		})
155		if exit == 0 {
156			t.Fatalf("expected non-zero exit for missing file, got 0")
157		}
158		if !strings.Contains(stderr, "cannot read graph file") {
159			t.Errorf("stderr = %q, want read error", stderr)
160		}
161	}
162	
163	func TestCLIInvalidJSONReturnsError(t *testing.T) {
164		graphPath := writeFile(t, "graph.json", `{"datasets":[]}`)
165		planPath := writeFile(t, "plan.json", `{not json`)
166		_, stderr, exit := captureStdout(t, func() int {
167			return run([]string{"preview", graphPath, planPath})
168		})
169		if exit == 0 {
170			t.Fatalf("expected non-zero exit for invalid JSON, got 0")
171		}
172		if !strings.Contains(stderr, "invalid plan JSON") {
173			t.Errorf("stderr = %q, want invalid plan JSON error", stderr)
174		}
175	}
176	
177	func TestCLIHelpAndVersion(t *testing.T) {
178		for _, tc := range []struct {
179			args []string
180			want string
181		}{
182			{[]string{"help"}, "preview"},
183			{[]string{"version"}, "0.2.0"},
184			{[]string{"demo"}, "roots"},
185		} {
186			stdout, _, exit := captureStdout(t, func() int {
187				return run(tc.args)
188			})
189			if exit != 0 {
190				t.Fatalf("%v exit = %d", tc.args, exit)
